#!/usr/bin/env node
/**
 * Mirror the CC: Tweaked documentation for the version pinned by TFGM.
 *
 * tweaked.cc is generated by illuaminate; this script pulls the rendered page
 * bodies (the `<section id="content">` subtree) so the site can serve the exact
 * CC:T reference locally, with links rewritten to this site and images cached
 * under `docs/public/`.
 *
 * Usage: node scripts/fetch-cc-docs.mjs [--version 1.121.0] [--force]
 */
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const args = new Map();
for (let i = 2; i < process.argv.length; i++) {
  const arg = process.argv[i];
  if (!arg.startsWith('--')) continue;
  const [key, inline] = arg.slice(2).split('=');
  args.set(key, inline ?? process.argv[++i] ?? 'true');
}

const VERSION = args.get('version') || '1.121.0';
const SOURCE = `https://tweaked.cc/mc-1.20.x`;
const OUT = resolve(ROOT, 'docs/data/cc');
const PUBLIC = resolve(ROOT, 'docs/public');
const CACHE = resolve(ROOT, '.cache/cc-docs', VERSION);
const FORCE = args.has('force');

async function fetchText(path) {
  const cachePath = path === '/' ? 'index.html' : path.replace(/^\/+/, '');
  const cached = join(CACHE, cachePath);
  if (!FORCE && existsSync(cached)) return readFileSync(cached, 'utf8');
  const response = await fetch(`${SOURCE}${path}`, { signal: AbortSignal.timeout(60_000) });
  if (!response.ok) throw new Error(`${path}: HTTP ${response.status}`);
  const text = await response.text();
  mkdirSync(dirname(cached), { recursive: true });
  writeFileSync(cached, text);
  return text;
}

async function fetchBinary(url) {
  const path = new URL(url).pathname;
  const cached = join(CACHE, 'assets', path.replace(/^\/+/, ''));
  if (!FORCE && existsSync(cached)) return readFileSync(cached);
  const response = await fetch(url, { signal: AbortSignal.timeout(60_000) });
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  const bytes = Buffer.from(await response.arrayBuffer());
  mkdirSync(dirname(cached), { recursive: true });
  writeFileSync(cached, bytes);
  return bytes;
}

function unwrap(html) {
  const section = /<section id="content">([\s\S]*?)<\/section>/.exec(html);
  if (!section) throw new Error('missing content section');
  return section[1];
}

function meta(html, name) {
  const match = new RegExp(`<meta (?:property|name)="${name}" content="([^"]*)"`).exec(html);
  return match ? decode(match[1]) : '';
}

function decode(value) {
  return String(value)
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
}

function stripTags(html) {
  return decode(String(html).replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
}

function parseNav(homeHtml) {
  const nav = /<div class="nav-links">([\s\S]*?)<\/div>/.exec(homeHtml);
  if (!nav) throw new Error('missing nav');
  const groups = [];
  const groupRe = /<h2[^>]*>(.*?)<\/h2><ul>([\s\S]*?)<\/ul>/g;
  for (const match of nav[1].matchAll(groupRe)) {
    const title = stripTags(match[1]);
    const pages = [];
    for (const link of match[2].matchAll(/<a href="([^"]+)" class="sidebar-link">([^<]+)<\/a>/g)) {
      const key = link[1].replace(/^\.\//, '');
      pages.push({ key, title: stripTags(link[2]) });
    }
    groups.push({ title, pages });
  }
  return groups;
}

function pageUrl(key) {
  const clean = key.replace(/\.html$/, '');
  return `/${clean}/`;
}

function tocFrom(content) {
  const toc = [];
  const seen = new Set();
  const re = /<a name="([^"]+)"[^>]*><\/a><span class="definition-name">([\s\S]*?)<\/span>/g;
  for (const match of content.matchAll(re)) {
    const id = match[1];
    if (seen.has(id)) continue;
    seen.add(id);
    toc.push({ id, title: stripTags(match[2]) });
  }
  return toc;
}

async function main() {
  console.log(`CC:T docs: ${SOURCE} -> ${OUT}`);
  const homeHtml = await fetchText('/');
  const groups = parseNav(homeHtml);

  const flat = [];
  for (const group of groups) for (const page of group.pages) flat.push({ ...page, group: group.title });

  const pages = new Map();
  for (const page of flat) {
    const html = await fetchText(`/${page.key}`);
    const content = unwrap(html);
    const title = page.title || meta(html, 'og:title');
    pages.set(page.key, {
      ...page,
      title,
      description: meta(html, 'description'),
      url: pageUrl(page.key),
      content,
      toc: tocFrom(content),
    });
  }

  const imageUrls = new Set();
  const localUrl = (key) => pages.get(key)?.url || (key === 'index' ? '/' : null);
  const rewriteUrl = (raw, page) => {
    if (!raw || raw.startsWith('#') || raw.startsWith('//')) return raw;
    if (/^(?:https?:|mailto:|data:)/i.test(raw)) return raw;
    let url;
    try {
      url = new URL(raw, `${SOURCE}/${page.key}`);
    } catch {
      return raw;
    }
    const hash = url.hash;
    const search = url.search;
    if (url.hostname === 'tweaked.cc') {
      let path = url.pathname;
      if (path.startsWith('/mc-1.20.x/')) path = path.slice('/mc-1.20.x/'.length);
      else if (path === '/') {
        return `/${search}${hash}`;
      }
      if (path.startsWith('/mc-1.20.x/')) path = path.slice('/mc-1.20.x'.length);
      if (/\.(?:png|jpe?g|gif|svg|webp)$/i.test(path)) {
        imageUrls.add(url.origin + url.pathname);
        return `/${path.replace(/^\/+/, '')}${search}${hash}`;
      }
      if (path.startsWith('/images/') || path.startsWith('/pack-')) {
        return `${path}${search}${hash}`;
      }
      const key = path.replace(/^\/+/, '');
      const mapped = localUrl(key) || localUrl(key.replace(/\.html$/, ''));
      if (mapped) return `${mapped}${search}${hash}`;
      return `${url.origin}${url.pathname}${search}${hash}`;
    }
    return raw;
  };

  for (const page of pages.values()) {
    page.content = page.content.replace(/\b(href|src)="([^"]+)"/g, (match, attr, raw) => {
      return `${attr}="${rewriteUrl(raw, page)}"`;
    });
    // Keep upstream external image hosts, but serve tweaked.cc assets locally.
    page.content = page.content.replace(/srcset="([^"]+)"/g, (match, value) => {
      const rewritten = value
        .split(',')
        .map((part) => {
          const [url, descriptor] = part.trim().split(/\s+/, 2);
          return `${rewriteUrl(url, page)}${descriptor ? ` ${descriptor}` : ''}`;
        })
        .join(', ');
      return `srcset="${rewritten}"`;
    });
  }

  const home = {
    key: 'index.html',
    title: 'CC: Tweaked',
    description: meta(homeHtml, 'description'),
    content: unwrap(homeHtml),
    toc: [],
    url: '/',
  };
  pages.set(home.key, home);
  home.content = home.content.replace(/\b(href|src)="([^"]+)"/g, (match, attr, raw) => {
    return `${attr}="${rewriteUrl(raw, home)}"`;
  });
  home.content = home.content.replace(/srcset="([^"]+)"/g, (match, value) => {
    const rewritten = value
      .split(',')
      .map((part) => {
        const [url, descriptor] = part.trim().split(/\s+/, 2);
        return `${rewriteUrl(url, home)}${descriptor ? ` ${descriptor}` : ''}`;
      })
      .join(', ');
    return `srcset="${rewritten}"`;
  });
  writeFileSync(join(OUT, 'home.html'), home.content);

  const iconUrl = meta(homeHtml, 'og:image');
  let logoPath = '/logo.png';
  if (iconUrl) {
    const logoUrl = new URL(iconUrl);
    logoPath = logoUrl.pathname;
    writeFileSync(join(PUBLIC, logoPath), await fetchBinary(iconUrl));
  }

  for (const url of imageUrls) {
    let path = new URL(url).pathname;
    if (path.startsWith('/mc-1.20.x/')) path = path.slice('/mc-1.20.x'.length);
    const bytes = await fetchBinary(url);
    const target = join(PUBLIC, path);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, bytes);
  }


  mkdirSync(join(OUT, 'pages'), { recursive: true });
  rmSync(join(OUT, 'pages'), { recursive: true, force: true });
  const manifest = { version: VERSION, source: SOURCE, logo: logoPath, home: { file: 'home.html', title: home.title, description: home.description }, groups: [], pages: {} };
  for (const group of groups) {
    const entry = { title: group.title, pages: [] };
    for (const page of group.pages) {
      const info = pages.get(page.key);
      const rel = `pages/${page.key.replace(/\.html$/, '.html')}`;
      const target = join(OUT, rel);
      mkdirSync(dirname(target), { recursive: true });
      writeFileSync(target, info.content);
      entry.pages.push({
        key: page.key,
        url: info.url,
        title: info.title,
        description: info.description,
        file: rel,
        toc: info.toc,
      });
      manifest.pages[info.url] = {
        title: info.title,
        description: info.description,
        group: group.title,
        file: rel,
        toc: info.toc,
      };
    }
    manifest.groups.push(entry);
  }
  writeFileSync(join(OUT, 'pages.json'), `${JSON.stringify(manifest, null, 2)}\n`);
  console.log(`Wrote ${Object.keys(manifest.pages).length} pages, ${imageUrls.size} images`);
}

main().catch((error) => {
  console.error(error.stack || error.message || String(error));
  process.exit(1);
});
